public class ServicoCheckout {

    public RespostaCheckout calcularResumo(RequisicaoCheckout requisicao) throws ErroCheckout {
        validarRequisicao(requisicao);

        BigDecimal subtotal = calcularSubtotal(requisicao.itens);

