public class CalcJuros {
    public static void main(String[] args) {
        BigDecimal total = new BigDecimal("425.30");
        BigDecimal taxa = new BigDecimal("0.0199");
        int parcelas = 6;

        BigDecimal numerador = total.multiply(taxa);
        System.out.println("Numerador: " + numerador);

        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);
        BigDecimal potencia = umMaisTaxa.pow(parcelas);
        System.out.println("(1 + taxa)^6: " + potencia);

        BigDecimal umDividoPotencia = BigDecimal.ONE.divide(potencia, 10, RoundingMode.HALF_EVEN);
        System.out.println("1 / (1 + taxa)^6: " + umDividoPotencia);

        BigDecimal denominador = BigDecimal.ONE.subtract(umDividoPotencia);
        System.out.println("1 - 1/(1+taxa)^6: " + denominador);

        BigDecimal parcela = numerador.divide(denominador, 10, RoundingMode.HALF_EVEN);
        System.out.println("Parcela bruta: " + parcela);

        BigDecimal parcelaArredondada = parcela.setScale(2, RoundingMode.HALF_EVEN);
        System.out.println("Parcela arredondada: " + parcelaArredondada);

        BigDecimal totalJuros = parcelaArredondada.multiply(new BigDecimal(parcelas));
        System.out.println("Total (6x): " + totalJuros);

        System.out.println("\nEsperado: 75.90");
        System.out.println("Total esperado: 455.40");
    }
}
